package com.brainserve.onboarding.tasks.api.controller;
import com.brainserve.onboarding.common.api.ApiResponse;import com.brainserve.onboarding.common.observability.RequestContext;import com.brainserve.onboarding.common.security.ClientPrincipal;import com.brainserve.onboarding.tasks.api.request.TransitionTaskRequest;import com.brainserve.onboarding.tasks.api.response.TaskResponse;import com.brainserve.onboarding.tasks.application.service.TaskService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/client-portal/tasks") @PreAuthorize("hasAuthority('CLIENT_PORTAL')") public class ClientTaskController {private final TaskService service;public ClientTaskController(TaskService service){this.service=service;}@GetMapping ApiResponse<List<TaskResponse>> list(@AuthenticationPrincipal ClientPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){var r=service.clientMine(p,page,size);return ApiResponse.success(r.items(),Map.of("page",r.page(),"size",r.size(),"totalElements",r.totalElements(),"totalPages",r.totalPages()),RequestContext.requestId());}@PostMapping("/{id}/transition") ApiResponse<TaskResponse> transition(@AuthenticationPrincipal ClientPrincipal p,@PathVariable UUID id,@Valid @RequestBody TransitionTaskRequest b,HttpServletRequest req){return ApiResponse.success(service.clientTransition(p,id,b,req),RequestContext.requestId());}}
